namespace SarmatVisionHold.Integration { public sealed class EkfSourceController { private readonly IVehicleGateway g;private int oldSet;private string oldMode;private bool changed;public EkfSourceController(IVehicleGateway g){this.g=g;}public bool Activate(int set,string mode){if(changed)return true;oldSet=g.CurrentEkfSourceSet;oldMode=g.CurrentMode;if(!g.SetEkfSourceSet(set)||!g.SetMode(mode)){Fallback("AltHold");return false;}changed=true;return true;}public void Fallback(string fallback){if(changed){g.SetEkfSourceSet(oldSet);g.SetMode(string.IsNullOrWhiteSpace(oldMode)?fallback:oldMode);}else g.SetMode(fallback);changed=false;} } }
